using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> returned type: {typedInfo.Type.Name}");

// Use the typed metadata to serialize
var forecast = new WeatherForecast("Seattle", 18.5);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Type the default resolver CAN resolve (any public type)
if (options.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? found))
    Console.WriteLine($"TryGet succeeded for {found!.Type.Name}");
else
    Console.WriteLine("TryGet failed for WeatherForecast (unexpected)");

// 2b. Options with a source-gen context that only knows about WeatherForecast
var limited = new JsonSerializerOptions { TypeInfoResolver = LimitedContext.Default };

if (limited.TryGetTypeInfo<WeatherForecast>(out _))
    Console.WriteLine("TryGet succeeded for WeatherForecast on limited context");

if (limited.TryGetTypeInfo<UnknownType>(out _))
    Console.WriteLine("TryGet succeeded for UnknownType (unexpected)");
else
    Console.WriteLine("TryGet returned false for UnknownType — no exception thrown");

// --- Types ---
public record WeatherForecast(string City, double TempC);
public record UnknownType(int Id);

[JsonSerializable(typeof(WeatherForecast))]          // only WeatherForecast
public partial class LimitedContext : JsonSerializerContext;

